// SPDX-License-Identifier: MIT
pragma solidity ^0.7.6;

/// @title IoT Device Firmware Registry with Feature Flags
/// @notice Manages firmware versions and feature toggles for IoT fleet
contract IoTFirmwareRegistry {

    struct DeviceProfile {
        uint256 deviceId;
        uint256 firmwareVersion;
        uint256 featureFlags;
        uint256 lastHeartbeat;
        uint256 energyBudget;
        address owner;
    }

    struct FirmwareUpdate {
        uint256 version;
        uint256 requiredFlags;
        uint256 energyCost;
        bytes32 checksum;
        bool active;
    }

    mapping(uint256 => DeviceProfile) public devices;
    mapping(uint256 => FirmwareUpdate) public firmwareUpdates;
    mapping(address => uint256[]) public ownerDevices;

    uint256 public constant FLAG_OTA_ENABLED = 0x01;
    uint256 public constant FLAG_SECURE_BOOT = 0x02;
    uint256 public constant FLAG_TELEMETRY = 0x04;
    uint256 public constant FLAG_LOW_POWER = 0x08;
    uint256 public constant FLAG_MESH_NETWORK = 0x10;

    uint256 public constant BASE_ENERGY_UNIT = 100;
    uint256 public constant HEARTBEAT_INTERVAL = 3600;

    uint256 private nextDeviceId;
    uint256 private nextFirmwareVersion;
    address public admin;

    event DeviceRegistered(uint256 indexed deviceId, address indexed owner);
    event FirmwareUpdated(uint256 indexed deviceId, uint256 newVersion);
    event EnergyReplenished(uint256 indexed deviceId, uint256 amount);
    event FeatureFlagsChanged(uint256 indexed deviceId, uint256 oldFlags, uint256 newFlags);

    modifier onlyAdmin() {
        require(msg.sender == admin, "Not admin");
        _;
    }

    modifier onlyDeviceOwner(uint256 deviceId) {
        require(devices[deviceId].owner == msg.sender, "Not device owner");
        _;
    }

    constructor() {
        admin = msg.sender;
        nextDeviceId = 1;
        nextFirmwareVersion = 1;
    }

    function registerDevice(uint256 initialFlags) external returns (uint256) {
        uint256 deviceId = nextDeviceId++;
        devices[deviceId] = DeviceProfile({
            deviceId: deviceId,
            firmwareVersion: 0,
            featureFlags: initialFlags,
            lastHeartbeat: block.timestamp,
            energyBudget: BASE_ENERGY_UNIT * 10,
            owner: msg.sender
        });
        ownerDevices[msg.sender].push(deviceId);
        emit DeviceRegistered(deviceId, msg.sender);
        return deviceId;
    }

    function publishFirmware(
        uint256 requiredFlags,
        uint256 energyCost,
        bytes32 checksum
    ) external onlyAdmin returns (uint256) {
        uint256 version = nextFirmwareVersion++;
        firmwareUpdates[version] = FirmwareUpdate({
            version: version,
            requiredFlags: requiredFlags,
            energyCost: energyCost,
            checksum: checksum,
            active: true
        });
        return version;
    }

    /// @notice Calculates the effective energy cost considering active feature flags
    /// @dev Energy cost is reduced by the number of optimization flags active
    function _calculateEffectiveEnergyCost(
        uint256 baseCost,
        uint256 activeFlags
    ) internal pure returns (uint256) {
        uint256 optimizationCount = 0;

        // Count optimization-related flags
        if (activeFlags & FLAG_LOW_POWER != 0) optimizationCount += 2;
        if (activeFlags & FLAG_MESH_NETWORK != 0) optimizationCount += 1;
        if (activeFlags & FLAG_TELEMETRY != 0) optimizationCount += 1;

        // Apply discount: each optimization point reduces cost by BASE_ENERGY_UNIT
        uint256 discount = optimizationCount * BASE_ENERGY_UNIT;

        // Underflow possible here in Solidity <0.8.0 when discount > baseCost
        return baseCost - discount;
    }

    /// @notice Applies firmware update to a device
    function applyFirmwareUpdate(
        uint256 deviceId,
        uint256 targetVersion
    ) external onlyDeviceOwner(deviceId) {
        DeviceProfile storage device = devices[deviceId];
        FirmwareUpdate storage fw = firmwareUpdates[targetVersion];

        require(fw.active, "Firmware not active");
        require(targetVersion > device.firmwareVersion, "Must upgrade");
        require(
            device.featureFlags & fw.requiredFlags == fw.requiredFlags,
            "Missing required flags"
        );

        uint256 effectiveCost = _calculateEffectiveEnergyCost(
            fw.energyCost,
            device.featureFlags
        );

        // With underflow, effectiveCost wraps to a huge number
        // But the subtraction below will also underflow, giving device massive energy
        device.energyBudget = device.energyBudget - effectiveCost;
        device.firmwareVersion = targetVersion;

        emit FirmwareUpdated(deviceId, targetVersion);
    }

    /// @notice Toggle feature flags on a device
    function setFeatureFlags(
        uint256 deviceId,
        uint256 newFlags
    ) external onlyDeviceOwner(deviceId) {
        DeviceProfile storage device = devices[deviceId];
        uint256 oldFlags = device.featureFlags;

        // Transitioning flags costs energy proportional to changes
        uint256 changedBits = oldFlags ^ newFlags;
        uint256 transitionCost = _countBits(changedBits) * (BASE_ENERGY_UNIT / 10);

        require(device.energyBudget >= transitionCost, "Insufficient energy");
        device.energyBudget -= transitionCost;
        device.featureFlags = newFlags;

        emit FeatureFlagsChanged(deviceId, oldFlags, newFlags);
    }

    function replenishEnergy(uint256 deviceId) external payable onlyDeviceOwner(deviceId) {
        require(msg.value >= 0.001 ether, "Minimum payment");
        uint256 energyUnits = (msg.value / 0.001 ether) * BASE_ENERGY_UNIT;
        devices[deviceId].energyBudget += energyUnits;
        emit EnergyReplenished(deviceId, energyUnits);
    }

    function heartbeat(uint256 deviceId) external onlyDeviceOwner(deviceId) {
        devices[deviceId].lastHeartbeat = block.timestamp;
    }

    function _countBits(uint256 x) internal pure returns (uint256 count) {
        while (x != 0) {
            count += x & 1;
            x >>= 1;
        }
    }

    function getDeviceInfo(uint256 deviceId) external view returns (
        uint256 firmwareVersion,
        uint256 featureFlags,
        uint256 energyBudget,
        uint256 lastHeartbeat
    ) {
        DeviceProfile storage d = devices[deviceId];
        return (d.firmwareVersion, d.featureFlags, d.energyBudget, d.lastHeartbeat);
    }

    function withdrawFunds() external onlyAdmin {
        payable(admin).transfer(address(this).balance);
    }
}
